//! Replays `testdata/port/ingest/paperless-verify.json`, generated by the real
//! Go `TestPortPaperlessVerifyContract`: documents are imported with `Run`
//! against a loopback fake Paperless API, the vault/archive/state are mutated
//! as scripted (deleted/corrupted/edited/copied files, foreign notes, state
//! changes) and `Verify` must produce Go's report for every step.
#![cfg(unix)]

use regex::Regex;
use serde_json::{Value, json};
use std::io::Write as _;
use std::path::Path;
use std::sync::{Arc, Mutex};
use symdesk_ingest::extract::Extraction;
use symdesk_ingest::ocr::Context;
use symdesk_ingest::paperless_run::{Options, Sink, run};
use symdesk_ingest::paperless_verify::verify;
use symdesk_ingest::pipeline::{Engine, Pipeline};
use symdesk_ingest::writer::NoteWriter;
use symdesk_ingest::Store;

#[path = "support/paperless_server.rs"]
mod paperless_server;
use paperless_server::{Server, routes_from};

/// `TMPDIR` is process-global; scenarios run one at a time.
static ENV_LOCK: Mutex<()> = Mutex::new(());

struct RunEngine;

impl Engine for RunEngine {
    fn extract(&self, _ctx: &Context, path: &str, kind: &str) -> Result<Extraction, String> {
        let bytes = std::fs::read(path).unwrap_or_default();
        Ok(Extraction {
            text: format!("extracted {} bytes", bytes.len()),
            mime: kind.to_owned(),
            engine: "fake".to_owned(),
            language: String::new(),
        })
    }
}

fn fixture() -> Value {
    let f: Value = serde_json::from_slice(
        &std::fs::read(
            Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("../../testdata/port/ingest/paperless-verify.json"),
        )
        .unwrap(),
    )
    .unwrap();
    assert_eq!(f["schema_version"], 1);
    f
}

fn find_note(vault: &Path, id: i64) -> std::path::PathBuf {
    fn walk(dir: &Path, prefix: &str) -> Option<std::path::PathBuf> {
        let mut entries: Vec<_> = std::fs::read_dir(dir)
            .ok()?
            .map(|e| e.unwrap().path())
            .collect();
        entries.sort();
        for path in entries {
            if path.is_dir() {
                if let Some(found) = walk(&path, prefix) {
                    return Some(found);
                }
            } else {
                let name = path.file_name().unwrap().to_string_lossy();
                if name.starts_with(prefix) && name.ends_with(".md") {
                    return Some(path);
                }
            }
        }
        None
    }
    walk(vault, &format!("paperless-{id}-")).unwrap_or_else(|| panic!("no note for {id}"))
}

fn archive_of(note: &Path) -> String {
    let text = std::fs::read_to_string(note).unwrap();
    let re = Regex::new(r"(?m)^archive_path: (.+)$").unwrap();
    re.captures(&text).unwrap()[1]
        .trim_matches(['"', '\''])
        .to_owned()
}

fn observe(case: &Value, scratch: &Path) -> Value {
    let sc = &case["scenario"];
    let id = sc["id"].as_str().unwrap();
    let _guard = ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let root = std::fs::canonicalize(scratch).unwrap().join(id);
    let _ = std::fs::remove_dir_all(&root);
    let tmp = root.join("tmp");
    std::fs::create_dir_all(&tmp).unwrap();
    // SAFETY: serialized by ENV_LOCK; the server thread never reads it.
    unsafe { std::env::set_var("TMPDIR", &tmp) };
    let server = Server::start(routes_from(&sc["routes"]));
    let base_url = format!("http://{}", server.host);
    let vault = root.join("vault");
    let archive = root.join("archive");
    let run_id = Regex::new(r"paperless-\d{8}T\d{6}\.\d{9}Z").unwrap();
    let tmp_re = Regex::new(r"\.tmp-\d+|symingest-import-\d+").unwrap();
    let norm = |s: &str| -> String {
        let s = s
            .replace(root.to_str().unwrap(), "<ROOT>")
            .replace(&server.host, "<HOST>");
        let s = run_id.replace_all(&s, "paperless-<RUN>").into_owned();
        tmp_re.replace_all(&s, "<TMP>").into_owned()
    };

    let store = Arc::new(Mutex::new(Store::open(&root.join("db/docs.db")).unwrap()));
    let mut pipeline = Pipeline::new(Arc::clone(&store), NoteWriter::new(vault.to_str().unwrap()));
    pipeline.engine = Some(Arc::new(RunEngine));
    pipeline.archive_dir = archive.to_string_lossy().into_owned();
    pipeline.log = Box::new(|_| {});
    let quiet: Sink = Arc::new(|_| {});
    let imported = run(
        &Options {
            base_url: base_url.clone(),
            token: "test-token".to_owned(),
            progress: Some(quiet.clone()),
            stderr: quiet.clone(),
            log: quiet,
            ..Options::default()
        },
        &pipeline,
    );
    assert!(imported.error.is_none(), "{id}: import failed");
    let imported_count = imported.stats.unwrap().imported;

    for m in sc["mutations"].as_array().map(Vec::as_slice).unwrap_or_default() {
        let doc = m["doc"].as_i64().unwrap_or(0);
        match m["op"].as_str().unwrap() {
            "rm-note" => std::fs::remove_file(find_note(&vault, doc)).unwrap(),
            "rm-archive" => {
                std::fs::remove_file(archive_of(&find_note(&vault, doc))).unwrap();
            }
            "corrupt-archive" => {
                let mut f = std::fs::OpenOptions::new()
                    .append(true)
                    .open(archive_of(&find_note(&vault, doc)))
                    .unwrap();
                f.write_all(b"tampered").unwrap();
            }
            "edit-note" => {
                let path = find_note(&vault, doc);
                let text = std::fs::read_to_string(&path).unwrap();
                let find = m["find"].as_str().unwrap();
                assert!(text.contains(find), "{id}: {find:?} not in note:\n{text}");
                std::fs::write(&path, text.replacen(find, m["replace"].as_str().unwrap(), 1))
                    .unwrap();
            }
            "copy-note" => {
                let path = find_note(&vault, doc);
                let copy = path
                    .with_file_name(format!("copy-{}", path.file_name().unwrap().to_string_lossy()));
                std::fs::copy(&path, copy).unwrap();
            }
            "write-file" => {
                let path = root.join(m["path"].as_str().unwrap());
                std::fs::create_dir_all(path.parent().unwrap()).unwrap();
                std::fs::write(path, m["content"].as_str().unwrap()).unwrap();
            }
            "state-status" => {
                let guard = store.lock().unwrap();
                let state = guard
                    .paperless_import_state_for_target(
                        &base_url,
                        vault.to_str().unwrap(),
                        archive.to_str().unwrap(),
                        doc,
                    )
                    .unwrap();
                guard
                    .upsert_paperless_import_state_for_target(
                        &symdesk_ingest::PaperlessStateWrite {
                            base_url: &base_url,
                            target_vault: vault.to_str().unwrap(),
                            target_archive: archive.to_str().unwrap(),
                            document_id: doc,
                            status: m["status"].as_str().unwrap(),
                            last_error: "",
                            vault_path: &state.vault_path,
                            archive_path: &state.archive_path,
                            sha256: &state.sha256,
                        },
                    )
                    .unwrap();
            }
            other => panic!("unknown mutation {other}"),
        }
    }

    let mut verifies = Vec::new();
    for spec in sc["verifies"].as_array().unwrap() {
        server
            .routes
            .lock()
            .unwrap()
            .extend(routes_from(&spec["routes_after"]));
        let opts = Options {
            base_url: base_url.clone(),
            token: "test-token".to_owned(),
            deep_verify: spec["deep"].as_bool().unwrap_or(false),
            ids: spec["ids"]
                .as_array()
                .map(|a| a.iter().map(|v| v.as_i64().unwrap()).collect())
                .unwrap_or_default(),
            limit: spec["limit"].as_u64().unwrap_or(0) as usize,
            target_vault: spec["target_vault"]
                .as_str()
                .unwrap_or("")
                .replace("<VAULT>", vault.to_str().unwrap()),
            target_archive: spec["target_archive"]
                .as_str()
                .unwrap_or("")
                .replace("<ARCHIVE>", archive.to_str().unwrap()),
            ..Options::default()
        };
        let target = match spec["vault_override"].as_str().unwrap_or("") {
            "none" => String::new(),
            "missing" => root.join("no-such-vault").to_string_lossy().into_owned(),
            "file" => {
                let path = root.join("vault-as-file");
                std::fs::write(&path, "x").unwrap();
                path.to_string_lossy().into_owned()
            }
            _ => vault.to_string_lossy().into_owned(),
        };
        let guard = store.lock().unwrap();
        let used = spec["use_store"].as_bool().unwrap_or(false).then_some(&*guard);
        let outcome = verify(&opts, &target, used);
        drop(guard);
        let mut obs = serde_json::Map::new();
        match outcome {
            Err(e) => {
                obs.insert("error".into(), json!(norm(&e)));
            }
            Ok(report) => {
                obs.insert("error".into(), json!(""));
                let mut value: Value =
                    serde_json::from_str(&norm(&serde_json::to_string(&report).unwrap())).unwrap();
                for key in ["started_at", "finished_at", "duration_seconds"] {
                    if value.get(key).is_some() {
                        value[key] = json!("<T>");
                    }
                }
                value["complete"] = json!(report.complete());
                obs.insert("report".into(), value);
            }
        }
        verifies.push(Value::Object(obs));
    }
    drop(pipeline);
    drop(store);
    let _ = server.finish();
    json!({"imported": imported_count, "verifies": verifies})
}

fn diff(path: &str, want: &Value, got: &Value, out: &mut Vec<String>) {
    match (want, got) {
        (Value::Object(a), Value::Object(b)) => {
            for key in a.keys().chain(b.keys()).collect::<std::collections::BTreeSet<_>>() {
                diff(
                    &format!("{path}.{key}"),
                    a.get(key).unwrap_or(&Value::Null),
                    b.get(key).unwrap_or(&Value::Null),
                    out,
                );
            }
        }
        (Value::Array(a), Value::Array(b)) if a.len() == b.len() => {
            for (i, (x, y)) in a.iter().zip(b).enumerate() {
                diff(&format!("{path}[{i}]"), x, y, out);
            }
        }
        _ => {
            if want != got {
                out.push(format!("{path}: go {want} rust {got}"));
            }
        }
    }
}

fn compare(case: &Value, scratch: &Path) -> Vec<String> {
    let observed = observe(case, scratch);
    let mut diffs = Vec::new();
    diff("imported", &case["imported"], &observed["imported"], &mut diffs);
    diff("verifies", &case["verifies"], &observed["verifies"], &mut diffs);
    diffs
}

#[test]
fn paperless_verify_matches_go() {
    let fx = fixture();
    let cases = fx["cases"].as_array().unwrap();
    assert!(cases.len() >= 25, "scenarios shrank: {}", cases.len());
    let scratch = Path::new(env!("CARGO_TARGET_TMPDIR")).join(format!("paperless-verify-{}", std::process::id()));
    std::fs::create_dir_all(&scratch).unwrap();
    let mut failures = Vec::new();
    for case in cases {
        let id = case["scenario"]["id"].as_str().unwrap();
        for d in compare(case, &scratch).into_iter().take(6) {
            failures.push(format!("{id}: {d}"));
        }
    }
    let _ = std::fs::remove_dir_all(&scratch);
    assert!(
        failures.is_empty(),
        "{} differences:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn paperless_verify_negative_controls_are_caught() {
    let fx = fixture();
    let cases = fx["cases"].as_array().unwrap();
    let scratch = Path::new(env!("CARGO_TARGET_TMPDIR")).join(format!("paperless-verify-neg-{}", std::process::id()));
    std::fs::create_dir_all(&scratch).unwrap();
    let case = cases
        .iter()
        .find(|c| c["scenario"]["id"] == "edited-note-metadata")
        .unwrap();
    assert!(compare(case, &scratch).is_empty());
    for mutate in [
        |c: &mut Value| c["verifies"][0]["report"]["verified"] = json!(3),
        |c: &mut Value| c["verifies"][0]["report"]["mismatches"][0]["got"] = json!("x"),
        |c: &mut Value| c["verifies"][1]["report"]["complete"] = json!(true),
        |c: &mut Value| c["verifies"][0]["error"] = json!("boom"),
    ] {
        let mut tampered = case.clone();
        mutate(&mut tampered);
        assert!(!compare(&tampered, &scratch).is_empty(), "tampering went unnoticed");
    }
    let _ = std::fs::remove_dir_all(&scratch);
}
